-- rhk-water-rooihuiskraal (owner)
UPDATE businesses SET description = 'RHK Water is a water-purification business located at 100 Maraboe Avenue, on the corner of Maraboe and Uitsig in Rooihuiskraal, Centurion. The company supplies purified drinking water to households, individuals and other local customers in the surrounding area. Operating as a dedicated water-purification outlet, RHK Water serves the local community with trading hours from Monday to Friday 08:00 to 18:00, Saturday 08:00 to 14:00, and Sunday 09:00 to 13:00, giving customers several opportunities each week to collect purified water at times that suit a range of schedules. As a neighbourhood supplier, RHK Water focuses on providing a reliable, accessible source of purified drinking water for residents of Rooihuiskraal and nearby parts of Centurion, functioning as a convenient, local alternative to tap water for everyday household use and for individuals wanting a dedicated purified-water source close to home.', description_enriched_at = datetime('now') WHERE slug = 'rhk-water-rooihuiskraal' AND description = 'RHK Water is a water treatment service on the corner of Maraboe and Uitsig in Rooihuiskraal, supplying alkaline mineral water and other health products to the local community.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
