UPDATE businesses SET description = 'Ring Mobile (Pty) Ltd, trading as Telsys Communications Mpumalanga BK t/a Ringmobile, provides internet-based telephone services from its Montana Park premises at 905 Braam Pretorius Street, Pretoria. The company offers CloudPBX and VoIP solutions that let home users and businesses make and receive calls over their existing internet connection, with a full range of PBX features built in. Customers can choose between flexible prepaid, debit order or post-paid calling plans, allowing both households and organisations to select a billing arrangement that suits their calling patterns without being tied to a fixed monthly subscription. Ring Mobile positions its service as a flexible alternative to traditional landline telephony, aimed at businesses wanting a scalable office phone system as well as home users wanting an affordable way to make calls. The company''s Montana Park office operates Monday to Friday from 08:00 to 17:00.', description_enriched_at = datetime('now') WHERE slug = 'ring-mobile-pty-ltd-montana-park' AND description = 'Ring Mobile provides a cloud-based PBX phone system that lets businesses make and receive calls over the internet on mobile, desk phone or computer, with no monthly subscription.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
