UPDATE businesses SET description = 'RRR Rams Holdings (Pty) Ltd is a waste-management company headquartered at 76 Makhosionke Street in Lotus Gardens, Pretoria. Founded in 2016, the company provides commercial and industrial waste collection, recycling and waste-logistics services to businesses and industrial customers. Beyond waste management, RRR Rams Holdings offers a broader range of support services, including cleaning, transport, general maintenance, garden and landscaping work, construction-related services, and supply services, positioning itself as a multi-service provider for commercial and industrial clients. While the company''s marketing has at times emphasised its presence and project work in the greater Johannesburg area, its own published information confirms Lotus Gardens as its head office, and the company lists Pretoria as its headquarters location. From this base, RRR Rams Holdings serves businesses across Gauteng that require combined waste, recycling and facilities-support services, bringing together logistics, environmental and maintenance capabilities under a single provider.', description_enriched_at = datetime('now') WHERE slug = 'rrr-rams-holdings-pty-ltd-lotus-gardens' AND description = 'RRR Rams Holdings is a waste management company also offering construction, cleaning, supply, transport, maintenance and garden services, established in 2016 and serving Lotus Gardens, Pretoria and surrounds.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
