UPDATE businesses SET description = 'Sello B Letsoalo Attorneys Inc. is a legal practice based at 609 Paul Kruger Street in Eloffsdal, Pretoria, offering attorney and legal-representation services to individuals, families and businesses. The firm''s Eloffsdal address is confirmed by the Legal Practice Council''s 2026 National Wills Week listing, which includes the practice among participating firms at this location, and is independently corroborated by earlier Government Gazette records showing the same Paul Kruger Street address. Operating from this long-established Pretoria base, the firm provides legal representation and advice to clients across a range of civil and personal legal matters, serving the Eloffsdal community and surrounding areas of Pretoria. Its participation in National Wills Week reflects a practice area that includes wills and estate-related legal services, alongside the firm''s general legal-practice work for individual, family and business clients in the area.', description_enriched_at = datetime('now') WHERE slug = 'sello-b-letsoalo-attorneys-inc-eloffsdal' AND description = 'SELLO B LETSOALO ATTORNEYS INC. is a law firm in Eloffsdal, Pretoria, that describes itself on its own website as offering dedicated, personalised legal solutions to its clients.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
