UPDATE businesses SET description = 'Spares Wise East Lynne is an aftermarket motor-spares retailer based at 171 Stormvoel Road in East Lynne, Pretoria. The store sells replacement vehicle parts and car accessories to private vehicle owners, everyday motorists and workshops in the surrounding area. Customers can buy parts directly in-store, arrange in-store pickup after ordering, or have parts delivered, with the branch offering same-day delivery as well as delivery to off-site locations for customers who cannot collect in person. This combination of in-store purchasing, pickup and flexible delivery options is aimed at making it easier for both individual vehicle owners and repair workshops to source replacement parts quickly, whether for routine maintenance or more urgent repairs. As a neighbourhood motor-spares outlet, Spares Wise East Lynne serves the East Lynne community and surrounding parts of Pretoria, providing a local alternative to dealership parts counters for motorists needing aftermarket components for their vehicles.', description_enriched_at = datetime('now') WHERE slug = 'spares-wise-east-lynne-east-lynne' AND description = 'Spares Wise East-Lynne is an aftermarket auto parts retailer offering performance parts, interior and exterior accessories, and expert consultation on replacement parts for a wide range of vehicles.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
