UPDATE businesses SET description = 'Studio Cut & Edge Silverton operates from 237 Roberts Street in Silverton, Pretoria, supplying wood-based boards and offering cut-and-edge processing services for customers planning kitchens, cabinetry and other furniture projects. The business works from customised cut lists and produces 3D designs and spatial-planning layouts to help customers visualise and plan their cabinetry or furniture projects before boards are cut and edged to size. In addition to board-cutting services, Studio Cut & Edge Silverton offers granite installations and kitchen and cabinetry installation, giving customers a combined supply-and-installation option for kitchen and furniture projects. The business serves homeowners undertaking home-renovation projects, as well as contractors and interior and design professionals who need cut-to-size boards and edging work for client projects. Studio Cut & Edge Silverton trades from its Silverton premises on weekdays and Saturdays, and is independently listed by Blum South Africa as a distributor operating from the same Roberts Street address, reflecting its established position as a supplier for cabinetry and furniture-making materials in the Pretoria area.', description_enriched_at = datetime('now') WHERE slug = 'studio-cut-edge-silverton-salieshoek' AND description = 'Studio Cut & Edge Silverton is a wood and plywood supplier in Silverton, Pretoria, offering kitchen-remodelling materials and custom furniture such as TV stands and other wood pieces.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
